import { useEffect, useState } from "react";
import {
  fillTemplateLine,
  getRootTemplateLines,
  getTemplateLineFields,
  loadReportTemplateTexts,
} from "../services/reportTemplateCache";

const GENERATED_FIELDS = ["GeneratedBy", "GeneratedOn"];

/**
 * Report-level lines from the backend report template, filled with report values:
 * the "Generated By / On" lines and the summary lines (Name, Date From, ...).
 */
export const useReportTemplateLines = (reportName, getValue) => {
  const [templateLines, setTemplateLines] = useState([]);

  useEffect(() => {
    let active = true;
    loadReportTemplateTexts(reportName)
      .then((texts) => {
        if (active) setTemplateLines(getRootTemplateLines(texts));
      })
      .catch(() => {
        // Without the template the report still shows its table.
      });
    return () => {
      active = false;
    };
  }, [reportName]);

  const isGeneratedLine = (text) =>
    getTemplateLineFields(text).some((field) => GENERATED_FIELDS.includes(field));
  const fill = (text) => fillTemplateLine(text, getValue);
  // "Name : {root.UserNames}" -> { label: "Name", value: <report UserNames> }
  const toItem = (text) => {
    const field = getTemplateLineFields(text)[0];
    return { field, label: text.split(" : ")[0].trim(), value: getValue(field) };
  };

  const generatedTemplates = templateLines
    .filter(isGeneratedLine)
    .sort((first, second) =>
      getTemplateLineFields(first)[0].localeCompare(getTemplateLineFields(second)[0]),
    );
  const summaryTemplates = templateLines.filter((text) => !isGeneratedLine(text));

  return {
    generatedLines: generatedTemplates.map(fill),
    summaryLines: summaryTemplates.map(fill),
    generatedItems: generatedTemplates.map(toItem),
    summaryItems: summaryTemplates.map(toItem),
  };
};
